def bind_arguments(parameters, args, kwargs):
    args = list(args)
    kwargs = dict(kwargs)
    result = {}

    var_pos_name = None
    var_kw_name = None
    for p in parameters:
        if p["kind"] == "VAR_POSITIONAL":
            var_pos_name = p["name"]
        elif p["kind"] == "VAR_KEYWORD":
            var_kw_name = p["name"]

    # Phase 1: bind positional arguments left to right.
    ai = 0
    for p in parameters:
        kind = p["kind"]
        if kind == "VAR_POSITIONAL":
            result[p["name"]] = list(args[ai:])
            ai = len(args)
            break
        if kind in ("POSITIONAL_ONLY", "POSITIONAL_OR_KEYWORD"):
            if ai < len(args):
                result[p["name"]] = args[ai]
                ai += 1
            # else leave unbound; keyword/default may fill it later
        else:
            # KEYWORD_ONLY / VAR_KEYWORD cannot receive positionals
            break

    if ai < len(args):
        raise TypeError("too many positional arguments")

    # Phase 2: bind keyword arguments.
    kw_targets = {}
    for p in parameters:
        if p["kind"] in ("POSITIONAL_OR_KEYWORD", "KEYWORD_ONLY"):
            kw_targets[p["name"]] = p

    extra_kw = {}
    for key, val in kwargs.items():
        if key in kw_targets:
            if key in result:
                raise TypeError("multiple values for argument '%s'" % key)
            result[key] = val
        else:
            if var_kw_name is not None:
                extra_kw[key] = val
            else:
                raise TypeError("unexpected keyword argument '%s'" % key)
    if var_kw_name is not None:
        result[var_kw_name] = extra_kw

    # Phase 3: apply defaults / verify required parameters.
    for p in parameters:
        name = p["name"]
        kind = p["kind"]
        if kind == "VAR_POSITIONAL":
            result.setdefault(name, [])
        elif kind == "VAR_KEYWORD":
            result.setdefault(name, {})
        elif name not in result:
            if "default" in p:
                result[name] = p["default"]
            else:
                raise TypeError("missing a required argument: '%s'" % name)
    return result

