def fib_calls(n):
    """Return [fib(n), total_calls] for naive recursive Fibonacci.

    The call count is tracked by a decorator that stores the counter in a
    closure variable, so every invocation of the wrapped function (including
    recursive ones) is recorded. A fresh decorated function is built on each
    call, so the counter always starts at zero.
    """
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("n must be an int")
    if n < 0:
        raise ValueError("n must be non-negative")

    def count_calls(func):
        count = 0

        def wrapper(*args, **kwargs):
            nonlocal count
            count += 1
            return func(*args, **kwargs)

        def get_count():
            return count

        wrapper.get_count = get_count
        return wrapper

    @count_calls
    def fib(k):
        if k < 2:
            return k
        return fib(k - 1) + fib(k - 2)

    value = fib(n)
    return [value, fib.get_count()]

