class _Atomic:
    """Context manager giving all-or-nothing semantics to a mutable list.

    On __enter__ it snapshots the list. On __exit__, if the block raised, it
    restores the snapshot in place and returns True to suppress the exception
    so the surrounding loop keeps running.
    """

    def __init__(self, state):
        self._state = state

    def __enter__(self):
        self._snapshot = list(self._state)
        return self._state

    def __exit__(self, exc_type, exc, tb):
        if exc_type is not None:
            # roll the list back to the pre-batch snapshot, in place
            self._state[:] = self._snapshot
        # suppress any exception so the next batch still runs
        return True


def batch_apply(initial, batches):
    state = list(initial)
    for batch in batches:
        with _Atomic(state) as working:
            for op in batch:
                action = op[0]
                if action == "push":
                    working.append(op[1])
                elif action == "pop":
                    working.pop()
                elif action == "divide_top":
                    working[-1] = working[-1] // op[1]
                else:
                    raise ValueError("unknown operation: {!r}".format(action))
    return state

