def track_aliasing(initial, steps):
    a = list(initial)
    b = a  # b is an alias of a: the same list object
    env = {"a": a, "b": b}
    for op, target, arg in steps:
        if op == "iadd":
            # In-place augmented assignment: list.__iadd__ mutates the shared
            # object and returns self, so any alias sees the change and the
            # binding stays on the same object.
            env[target] += arg
        elif op == "concat":
            # Rebinding: builds a brand-new list and rebinds only this name,
            # breaking the alias with the other name.
            env[target] = env[target] + arg
        elif op == "append":
            env[target].append(arg)
        else:
            raise ValueError("unknown op: {!r}".format(op))
    return [env["a"], env["b"], env["a"] is env["b"]]

def analyze_orders(orders):
    if not orders:
        return {"common": [], "distinct_combos": 0}
    item_sets = [set(order) for order in orders]
    common = set(item_sets[0])
    for s in item_sets[1:]:
        common &= s
    distinct = {frozenset(s) for s in item_sets}
    return {"common": sorted(common), "distinct_combos": len(distinct)}

def merge_pairs(pairs):
    mapping = {}
    unhashable = 0
    for key, value in pairs:
        try:
            mapping[key] = value
        except TypeError:
