def bind_call(parameters, args, kwargs):
    POS_ONLY, POS_OR_KW, KW_ONLY, VAR_POS, VAR_KW = (
        "POS_ONLY", "POS_OR_KW", "KW_ONLY", "VAR_POS", "VAR_KW")

    params = []
    for p in parameters:
        name, kind = p[0], p[1]
        has_default = len(p) > 2 and p[2]
        default = p[3] if len(p) > 3 else None
        params.append({"name": name, "kind": kind,
                       "has_default": has_default, "default": default})

    var_pos = next((p for p in params if p["kind"] == VAR_POS), None)
    var_kw = next((p for p in params if p["kind"] == VAR_KW), None)

    bound = {}

    # 1. Fill positional-only / positional-or-keyword slots left to right.
    positional_slots = [p for p in params if p["kind"] in (POS_ONLY, POS_OR_KW)]
    args = list(args)
    if len(args) > len(positional_slots) and var_pos is None:
        return "TypeError"
    for i, value in enumerate(args):
        if i < len(positional_slots):
            bound[positional_slots[i]["name"]] = value
        else:
            bound.setdefault(var_pos["name"], [])
            bound[var_pos["name"]].append(value)

    # 2/3. Bind keywords by name; positional-only names & unknowns fall to **kwargs.
    by_name = {p["name"]: p for p in params}
    extra_kw = {}
    for key, value in kwargs.items():
        target = by_name.get(key)
        if target is not None and target["kind"] in (POS_OR_KW, KW_ONLY):
            if target["name"] in bound:
                return "TypeError"  # multiple values for argument
            bound[target["name"]] = value
        else:
            if var_kw is not None:
                extra_kw[key] = value
            else:
                return "TypeError"  # unexpected keyword argument

    # 4. Apply defaults / detect missing required.
    for p in params:
        if p["kind"] in (VAR_POS, VAR_KW):
            continue
        if p["name"] not in bound:
            if p["has_default"]:
                bound[p["name"]] = p["default"]
            else:
                return "TypeError"  # missing required argument

    # 5. Finalize the catch-all parameters.
    if var_pos is not None:
        bound.setdefault(var_pos["name"], [])
    if var_kw is not None:
        bound[var_kw["name"]] = extra_kw

    return bound

