def stacked_trace(specs):
    log = []

    def base():
        log.append("#")

    def make_decorator(name, mode):
        def decorator(inner):
            def wrapper():
                if mode == "wrap":
                    log.append(name + "(")
                    inner()
                    log.append(name + ")")
                elif mode == "skip":
                    log.append(name + "!")
                elif mode == "twice":
                    log.append(name + "[")
                    inner()
                    log.append(name + "|")
                    inner()
                    log.append(name + "]")
                else:
                    raise ValueError("unknown mode: " + str(mode))
            return wrapper
        return decorator

    # specs are top-to-bottom: specs[0] is outermost, specs[-1] innermost.
    # `@a @b def f` means f = a(b(f)), so the innermost (last) spec must
    # wrap the base first. Iterate in reverse to build the onion.
    func = base
    for name, mode in reversed(specs):
        func = make_decorator(name, mode)(func)

    func()
    return "".join(log)

