def split_ascending_runs(nums):
    """Split ``nums`` into maximal strictly-ascending runs.

    A generator builds each run and yields it the moment the strictly-
    increasing streak breaks; the final buffered run is flushed after the
    loop ends. ``list(...)`` drives the generator to exhaustion.
    """
    def runs(seq):
        run = []
        for x in seq:
            if run and x > run[-1]:
                run.append(x)
            else:
                if run:
                    yield run
                run = [x]
        if run:
            yield run
    return [list(r) for r in runs(nums)]

def count_dominated_points(points):
    # A point p is dominated iff some other point q is strictly greater on
    # BOTH axes. The strict comparison means p never dominates itself and
    # equal points never dominate each other, so we can scan all points
    # without excluding p explicitly. The outer generator expression yields
    # 1 per dominated point; the inner `any(...)` over a generator expression
    # short-circuits as soon as a dominating point is found.
    return sum(
        1
        for p in points
        if any(q[0] > p[0] and q[1] > p[1] for q in points)
    )

def analyze_value(value):
    class ValidationError(Exception):
        pass

    class ProcessingError(Exception):
        pass

    def validate(v):
        try:
            n = int(v)
            return 100 // n
        except Exception as exc:
            raise ValidationError("could not validate " + repr(v)) from exc

    def process(v):
        try:
            return validate(v)
        except ValidationError as exc:
            raise ProcessingError("processing failed") from exc

    try:
        result = process(value)
    except ProcessingError as exc:
        chain = []
        current = exc
        while current is not None:
            chain.append(type(current).__name__)
            current = current.__cause__
        return {"status": "error", "chain": chain}
    return {"status": "ok", "value": result}

