code.reference_solution:
from contextlib import contextmanager


class Abort(BaseException):
    pass


def run_frames(spec, body):
    log = []

    @contextmanager
    def frame(name, on_error):
        log.append("enter:" + name)
        try:
            yield
        except Exception as exc:
            log.append("catch:" + name)
            if on_error == "suppress":
                log.append("suppress:" + name)
                # falling through swallows the exception
            elif on_error == "reraise":
                log.append("reraise:" + name)
                raise
            elif on_error == "replace":
                log.append("replace:" + name)
                raise RuntimeError(name) from exc
            else:
                raise
        finally:
            log.append("exit:" + name)

    def run(i):
        if i == len(spec):
            if body == "error":
                raise ValueError("boom")
            elif body == "base":
                raise Abort("boom")
            return
        f = spec[i]
        with frame(f["name"], f["on_error"]):
            run(i + 1)

    error = None
    try:
        run(0)
    except BaseException as exc:
        error = type(exc).__name__ + ":" + str(exc)
    return {"log": log, "error": error}

from typing import List, Dict, Optional


def count_items(items: Optional[List[str]]) -> Dict[str, int]:
    counts: Dict[str, int] = {}
    if items is None:
        return counts
    for item in items:
        counts[item] = counts.get(item, 0) + 1
    return counts

from pathlib import PurePosixPath


def dedupe_paths(paths: list[str]) -> list[str]:
    def normalize(s: str) -> str:
        p = PurePosixPath(s)
        absolute = p.is_absolute()
        # For an absolute PurePosixPath, parts[0] is the anchor ('/' or the
        # POSIX two-slash '//'); drop it so we work only with real components.
        comps = list(p.parts[1:] if absolute else p.parts)
        stack: list[str] = []
        for c in comps:
            if c == "..":
                if stack and stack[-1] != "..":
                    stack.pop()
                elif absolute:
                    # '..' above the root of an absolute path is discarded.
                    continue
                else:
                    # Relative path: a non-cancellable '..' is preserved and
                    # accumulates (never cancels a preceding '..').
                    stack.append("..")
            else:
                stack.append(c)
        if absolute:
            return "/" + "/".join(stack)
        return "/".join(stack) if stack else "."

    return sorted({normalize(s) for s in paths})
